"""Gzips fridge_monitor/setup_page.html into fridge_monitor/setup_page.h.

Run after every edit of the page:  python make_setup_page.py
The board serves the gzipped bytes with Content-Encoding: gzip (about a quarter of the size).
"""
import gzip
import pathlib

here = pathlib.Path(__file__).resolve().parent / "fridge_monitor"
html = (here / "setup_page.html").read_bytes()
gz = gzip.compress(html, compresslevel=9, mtime=0)
rows = [", ".join(f"0x{b:02x}" for b in gz[i:i + 16]) for i in range(0, len(gz), 16)]
out = (
    "// Generated by make_setup_page.py from setup_page.html - do not edit by hand.\n"
    "#pragma once\n#include <Arduino.h>\n\n"
    f"const size_t SETUP_PAGE_GZ_LEN = {len(gz)};   // {len(html)} bytes before gzip\n"
    "const uint8_t SETUP_PAGE_GZ[] PROGMEM = {\n  " + ",\n  ".join(rows) + "\n};\n"
)
(here / "setup_page.h").write_text(out, encoding="ascii", newline="\n")
print(f"setup_page.h: {len(html)} -> {len(gz)} bytes")
